      out.write("        <div class=\"card card-panel mt-4 p-4\">\n");
      out.write("            <h4>Información del sistema</h4>\n");
      out.write("            <p>\n");
      out.write("                Este panel corresponde al proyecto SADU y sirve como punto de acceso\n");
      out.write("                a los módulos administrativos del sistema.\n");
