      out.write("    \n");
      out.write("\n");
      out.write("    <script>\n");
      out.write("        // Datos del usuario en sesión (pasados desde JSP a JS)\n");
      out.write("        const USUARIO_NOMBRE = \"");
      out.print( nombreUsuario );
      out.write("\";\n");
      out.write("        const USUARIO_ID     = ");
      out.print( idUsuario );
      out.write(";\n");
      out.write("\n");
      out.write("        // Estado del chat: abierto o cerrado\n");
      out.write("        let chatAbierto = false;\n");
      out.write("\n");
      out.write("        // Intervalo para refrescar mensajes automáticamente cada 8 segundos\n");
      out.write("        let intervaloChat = null;\n");
      out.write("\n");
      out.write("        /**\n");
      out.write("         * Abre o cierra la ventana del chat flotante.\n");
      out.write("         * Si se abre, carga los mensajes y activa el refresco automático.\n");
      out.write("         * Si se cierra, detiene el refresco automático.\n");
      out.write("         */\n");
      out.write("        function toggleChat() {\n");
      out.write("            const ventana = document.getElementById(\"chat-ventana\");\n");
      out.write("            chatAbierto = !chatAbierto;\n");
      out.write("\n");
      out.write("            if (chatAbierto) {\n");
      out.write("                // Mostrar ventana como flex para que el layout interno funcione\n");
      out.write("                ventana.style.display = \"flex\";\n");
      out.write("                cargarMensajes();\n");
      out.write("\n");
      out.write("                // Refrescar mensajes cada 8 segundos mientras el chat esté abierto\n");
      out.write("                intervaloChat = setInterval(cargarMensajes, 8000);\n");
      out.write("            } else {\n");
      out.write("                ventana.style.display = \"none\";\n");
      out.write("                // Detener el refresco al cerrar para no hacer peticiones innecesarias\n");
      out.write("                clearInterval(intervaloChat);\n");
      out.write("            }\n");
      out.write("        }\n");
      out.write("\n");
      out.write("        /**\n");
      out.write("         * Consulta los mensajes del chat llamando a ListarMensajesServlet.\n");
      out.write("         * El servlet devuelve el HTML del JSP, pero aquí usamos un endpoint\n");
      out.write("         * que devuelve JSON. Como aún no tenemos ese endpoint, llamamos al\n");
      out.write("         * servlet y extraemos los datos del atributo de sesión.\n");
      out.write("         *\n");
      out.write("         * SOLUCIÓN SIMPLE: usamos fetch al servlet de listado y mostramos\n");
      out.write("         * los mensajes parseando la respuesta en formato JSON simple.\n");
      out.write("         */\n");
      out.write("        function cargarMensajes() {\n");
      out.write("            fetch(\"ChatJsonServlet\")\n");
      out.write("                .then(function(res) {\n");
      out.write("                    if (!res.ok) throw new Error(\"Error HTTP: \" + res.status);\n");
      out.write("                    return res.json();\n");
      out.write("                })\n");
      out.write("                .then(function(mensajes) {\n");
      out.write("                    mostrarMensajes(mensajes);\n");
      out.write("                })\n");
      out.write("                .catch(function(err) {\n");
      out.write("                    document.getElementById(\"chat-mensajes\").innerHTML =\n");
      out.write("                        '<div class=\"cargando\">⚠️ No se pudieron cargar los mensajes.</div>';\n");
      out.write("                });\n");
      out.write("        }\n");
      out.write("\n");
      out.write("        /**\n");
      out.write("         * Renderiza la lista de mensajes en la ventana del chat.\n");
      out.write("         * Los mensajes del usuario actual aparecen a la derecha (burbuja azul).\n");
      out.write("         * Los mensajes de otros aparecen a la izquierda (burbuja gris).\n");
      out.write("         *\n");
      out.write("         * @param {Array} mensajes Lista de objetos {idUsuario, nombreUsuario, asunto, mensaje, fechaEnvio}\n");
      out.write("         */\n");
      out.write("        function mostrarMensajes(mensajes) {\n");
      out.write("            const area = document.getElementById(\"chat-mensajes\");\n");
      out.write("\n");
      out.write("            if (!mensajes || mensajes.length === 0) {\n");
      out.write("                area.innerHTML = '<div class=\"cargando\">📭 No hay mensajes aún.</div>';\n");
      out.write("                return;\n");
      out.write("            }\n");
      out.write("\n");
      out.write("            let html = \"\";\n");
      out.write("\n");
      out.write("            mensajes.forEach(function(m) {\n");
      out.write("                // Determinar si el mensaje es del usuario actual o de otro\n");
      out.write("                const esPropio = m.idUsuario === USUARIO_ID;\n");
      out.write("                const clase    = esPropio ? \"propio\" : \"otro\";\n");
      out.write("\n");
      out.write("                // Formatear la fecha para mostrar solo hora:minuto\n");
      out.write("                let hora = \"\";\n");
      out.write("                if (m.fechaEnvio) {\n");
      out.write("                    const fecha = new Date(m.fechaEnvio);\n");
      out.write("                    hora = fecha.toLocaleTimeString(\"es-CO\", {hour: \"2-digit\", minute: \"2-digit\"});\n");
      out.write("                }\n");
      out.write("\n");
      out.write("                html += '<div class=\"burbuja ' + clase + '\">';\n");
      out.write("\n");
      out.write("                // Solo mostrar remitente en mensajes de otros\n");
      out.write("                if (!esPropio) {\n");
      out.write("                    html += '<div class=\"remitente\">👤 ' + m.nombreUsuario + '</div>';\n");
      out.write("                }\n");
      out.write("\n");
      out.write("                html += '<strong style=\"font-size:12px;\">' + m.asunto + '</strong><br>';\n");
      out.write("                html += m.mensaje;\n");
      out.write("                html += '<div class=\"hora\">' + hora + '</div>';\n");
      out.write("                html += '</div>';\n");
      out.write("            });\n");
      out.write("\n");
      out.write("            area.innerHTML = html;\n");
      out.write("\n");
      out.write("            // Scroll automático al último mensaje\n");
      out.write("            area.scrollTop = area.scrollHeight;\n");
      out.write("        }\n");
      out.write("\n");
      out.write("        /**\n");
      out.write("         * Envía un nuevo mensaje al servidor usando EnviarMensajeServlet.\n");
      out.write("         * Usa fetch con método POST para no recargar la página.\n");
      out.write("         * Al enviar exitosamente, limpia los campos y recarga los mensajes.\n");
      out.write("         */\n");
      out.write("        function enviarMensaje() {\n");
      out.write("            const asunto  = document.getElementById(\"chat-asunto\").value.trim();\n");
      out.write("            const mensaje = document.getElementById(\"chat-mensaje\").value.trim();\n");
      out.write("\n");
